CREATE TABLE app_user (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, email varchar(255) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, role varchar(30) NOT NULL CHECK(role IN ('ADMIN','FURGONISTA','APODERADO','COLEGIO')), first_name varchar(255) NOT NULL, last_name varchar(255) NOT NULL, rut varchar(255), phone varchar(255), address varchar(255), active boolean NOT NULL DEFAULT true);
CREATE TABLE driver_profile (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, user_id uuid NOT NULL UNIQUE REFERENCES app_user(id), status varchar(40) NOT NULL CHECK(status IN ('INCOMPLETO','PENDIENTE_VERIFICACION','APROBADO','RECHAZADO')), photo_id uuid, bio varchar(2000), rejection_reason varchar(255));
CREATE TABLE vehicle (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, driver_id uuid NOT NULL UNIQUE REFERENCES driver_profile(id), plate varchar(255) NOT NULL UNIQUE, brand varchar(255) NOT NULL, model varchar(255) NOT NULL, manufacture_year integer NOT NULL, color varchar(255) NOT NULL, capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 60), photo_id uuid);
CREATE TABLE coverage_area (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, driver_id uuid NOT NULL REFERENCES driver_profile(id), region varchar(255) NOT NULL, commune varchar(255) NOT NULL, geometry_geo_json varchar(10000), latitude double precision, longitude double precision, radius_meters double precision, UNIQUE(driver_id,commune));
CREATE TABLE institution (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, owner_id uuid NOT NULL UNIQUE REFERENCES app_user(id), name varchar(255) NOT NULL, rbd varchar(255), address varchar(255), region varchar(255), commune varchar(255), phone varchar(255), email varchar(255), description varchar(2000), logo_id uuid, primary_color varchar(255) NOT NULL, secondary_color varchar(255) NOT NULL);
CREATE TABLE driver_institution (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, driver_id uuid NOT NULL REFERENCES driver_profile(id), institution_id uuid NOT NULL REFERENCES institution(id), UNIQUE(driver_id,institution_id));
CREATE TABLE guardian_institution (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, guardian_id uuid NOT NULL REFERENCES app_user(id), institution_id uuid NOT NULL REFERENCES institution(id), UNIQUE(guardian_id,institution_id));
CREATE TABLE driver_document (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, driver_id uuid NOT NULL REFERENCES driver_profile(id), type varchar(40) NOT NULL CHECK(type IN ('LICENCIA','ANTECEDENTES','HABILITACION_MENORES','FOTO_CONDUCTOR','FOTO_VEHICULO')), status varchar(30) NOT NULL CHECK(status IN ('PENDIENTE','APROBADO','RECHAZADO')), filename varchar(255) NOT NULL, content_type varchar(255) NOT NULL, content bytea NOT NULL, review_note varchar(255), UNIQUE(driver_id,type));
CREATE TABLE media_asset (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, owner_id uuid NOT NULL REFERENCES app_user(id), content_type varchar(255) NOT NULL, content bytea NOT NULL);
CREATE TABLE quote (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, guardian_id uuid NOT NULL REFERENCES app_user(id), driver_id uuid NOT NULL REFERENCES driver_profile(id), institution_id uuid NOT NULL REFERENCES institution(id), address varchar(255) NOT NULL, commune varchar(255) NOT NULL, suggested_price numeric(12,0) NOT NULL CHECK(suggested_price > 0), offered_price numeric(12,0) CHECK(offered_price > 0), status varchar(40) NOT NULL CHECK(status IN ('SOLICITADA','EN_REVISION','OFERTA_ENVIADA','ACEPTADA','RECHAZADA','CANCELADA')));
CREATE TABLE transport_contract (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, quote_id uuid NOT NULL UNIQUE REFERENCES quote(id), guardian_id uuid NOT NULL REFERENCES app_user(id), driver_id uuid NOT NULL REFERENCES driver_profile(id), vehicle_id uuid NOT NULL REFERENCES vehicle(id), institution_id uuid NOT NULL REFERENCES institution(id), student_id uuid, monthly_price numeric(12,0) NOT NULL CHECK(monthly_price > 0), status varchar(30) NOT NULL CHECK(status IN ('ACTIVO','CANCELADO')));
CREATE TABLE notification (id uuid PRIMARY KEY, created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, user_id uuid NOT NULL REFERENCES app_user(id), title varchar(255) NOT NULL, message varchar(2000) NOT NULL, quote_id uuid REFERENCES quote(id), read boolean NOT NULL DEFAULT false);
CREATE INDEX idx_contract_vehicle_status ON transport_contract(vehicle_id,status);
CREATE INDEX idx_quote_guardian ON quote(guardian_id);
CREATE INDEX idx_quote_driver ON quote(driver_id);
CREATE INDEX idx_notification_user ON notification(user_id);
CREATE INDEX idx_coverage_commune ON coverage_area(commune);
